INSERT INTO `services` (`id`, `name`, `eventColor`, `price`, `price_can_change`, `duration_minutes_min`, `duration_minutes`, `short_description`, `full_description`, `status`, `time_from`, `time_to`, `has_fixed_time`, `is_deleted`, `created_at`, `updated_at`) VALUES
(1, 'Mediitsiiniline pediküür/Медицинский педикюр', '#112dc8', 60.00, 1, 90, 90, 'Protseduur on suunatud küünte ja naha probleemide ennetamisele ja taastamisele.\r\n\r\nПроцедура направлена на восстановление и профилактику проблем ногтей и кожи.', '<p>Процедuur on suunatud k&uuml;&uuml;nte ja naha probleemide ennetamisele ja taastamisele. Selle viib l&auml;bi podoloog, kasutades steriilseid t&ouml;&ouml;riistu.</p>\r\n<p>Mida sisaldab?</p>\r\n<p>&bull; K&uuml;&uuml;nte t&ouml;&ouml;tlemine (sissekasvanud, paksenenud, kahjustatud k&uuml;&uuml;ned)</p>\r\n<p>&bull; K&otilde;vade nahat&uuml;kkide, konnasilmade ja l&otilde;hede eemaldamine</p>\r\n<p>&bull; K&uuml;&uuml;nte kuju korrigeerimine ja deformatsioonide ennetamine</p>\r\n<p>Kellele sobib?</p>\r\n<p>&bull; Inimestele, kellel on diabeet v&otilde;i vereringeh&auml;ired</p>\r\n<p>&bull; Neile, kellel on sissekasvanud k&uuml;&uuml;s v&otilde;i h&uuml;perkeratoos</p>\r\n<p><br>Процедура направлена на восстановление и профилактику проблем ногтей и кожи. Выполняется подологом с использованием стерильных инструментов.</p>\r\n<p><br><strong>Что включает?</strong></p>\r\n<ul>\r\n<li>Обработка ногтей (вросшие, утолщенные, поврежденные)</li>\r\n<li>Удаление натоптышей, мозолей, трещин</li>\r\n<li>Коррекция формы ногтей и профилактика деформаций</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>Кому подходит?</strong></p>\r\n<ul>\r\n<li>Людям с диабетом и нарушением кровообращения</li>\r\n<li>Тем, у кого вросший ноготь или гиперкератоз</li>\r\n</ul>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-04-19 10:50:21'),
(2, 'Mediitsiiniline pediküür “keeruline”/Медицинский педикюр «сложный»', '#1e425a', 75.00, 1, NULL, 120, 'Protseduur aitab keeruliste ja kaugele arenenud küünte ning naha probleemide korral./Процедура направлена на восстановление и профилактику проблем ногтей и кожи.', '<p>Protseduur aitab keeruliste ja kaugele arenenud k&uuml;&uuml;nte ning naha probleemide korral.</p>\r\n<p>Selle viib l&auml;bi spetsialist, kasutades steriilseid t&ouml;&ouml;riistu ja kaasaegseid metoodikaid.</p>\r\n<p>Mida sisaldab?</p>\r\n<p>&bull; Probleemsete k&uuml;&uuml;nte hooldus (sissekasvanud, paksenenud, kahjustatud v&otilde;i seeninfektsiooniga k&uuml;&uuml;ned)</p>\r\n<p>&bull; Jalanaha paksendite, konnasilmade ja s&uuml;gavate l&otilde;hede eemaldamine</p>\r\n<p>&bull; K&uuml;&uuml;nte kuju korrigeerimine ja deformatsioonide ennetamine</p>\r\n<p>&bull; Vajadusel individuaalne hooldus- v&otilde;i ravivahendite soovitus</p>\r\n<p>&nbsp;</p>\r\n<p>Kellele sobib?</p>\r\n<p>&bull; Diabeedi, vereringeh&auml;irete v&otilde;i neuropaatia all kannatavatele inimestele</p>\r\n<p>&bull; Neile, kellel on:</p>\r\n<p>&emsp;&ndash; sissekasvanud k&uuml;&uuml;ned</p>\r\n<p>&emsp;&ndash; h&uuml;perkeratoos v&otilde;i l&otilde;hed</p>\r\n<p>&emsp;&ndash; kroonilised v&otilde;i korduvad jalalaba ja k&uuml;&uuml;nte probleemid</p>\r\n<p><br>Процедура помогает при сложных и запущенных проблемах ногтей и кожи.</p>\r\n<p>Проводится специалистом с использованием стерильных инструментов и современных методик.</p>\r\n<p>&nbsp;</p>\r\n<p>Что включает?</p>\r\n<p>&bull; Обработка проблемных ногтей (вросшие, утолщённые, повреждённые, с грибковыми изменениями)</p>\r\n<p>&bull; Удаление натоптышей, мозолей, глубоких трещин</p>\r\n<p>&bull; Коррекция формы ногтей и профилактика деформаций</p>\r\n<p>&bull; Индивидуальный подбор уходовых или лечебных средств при необходимости</p>\r\n<p>&nbsp;</p>\r\n<p>Кому подходит?</p>\r\n<p>&bull; Людям с диабетом, нарушением кровообращения или нейропатией</p>\r\n<p>&bull; Тем, у кого:</p>\r\n<p>&emsp;&ndash; вросшие ногти</p>\r\n<p>&emsp;&ndash; гиперкератоз или трещины</p>\r\n<p>&emsp;&ndash; хронические или повторяющиеся проблемы стоп и ногтей</p>\r\n<p>&nbsp;</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-01-01 19:57:40'),
(3, 'Klassikaline pediküür/Классический педикюр', '#fc519c', 50.00, 0, 90, 90, 'Aitab säilitada jalgade tervist ja hoolitsetud välimust./Помогает сохранить здоровье и ухоженный вид стоп.', '<p>Klassikaline pedik&uuml;&uuml;r</p>\r\n<p>Aitab s&auml;ilitada jalgade tervist ja hoolitsetud v&auml;limust, pakkudes baashooldust nahale ja k&uuml;&uuml;ntele.</p>\r\n<p>&nbsp;</p>\r\n<p>Mida sisaldab?</p>\r\n<p>&bull; Jalgade naha pehmendamine</p>\r\n<p>&bull; K&uuml;&uuml;neplaadi puhastamine ja t&ouml;&ouml;tlemine</p>\r\n<p>&bull; Sarvestunud naha eemaldamine</p>\r\n<p>&bull; Niisutamine ja l&otilde;&otilde;gastav massaaž</p>\r\n<p>Protseduuri kasulikkus:</p>\r\n<p>&bull; L&otilde;hede ja paksendite ennetamine</p>\r\n<p>&bull; Jalgade v&auml;limuse ja mugavustunde parandamine</p>\r\n<p>&bull; H&uuml;gieeni ja kergustunde s&auml;ilitamine</p>\r\n<p>Soovitatav regulaarseks hoolduseks neile, kes hoolivad oma jalgade tervisest.</p>\r\n<p><br>Классический педикюр</p>\r\n<p>Помогает сохранить здоровье и ухоженный вид стоп, обеспечивая базовый уход за кожей и ногтями.</p>\r\n<p>Что включает?</p>\r\n<p>&bull; Размягчение кожи стоп</p>\r\n<p>&bull; Очищение и обработка ногтевой пластины</p>\r\n<p>&bull; Удаление ороговевшей кожи</p>\r\n<p>&bull; Увлажнение и расслабляющий массаж</p>\r\n<p>Польза процедуры:</p>\r\n<p>&bull; Профилактика трещин и натоптышей</p>\r\n<p>&bull; Улучшение внешнего вида и комфорта стоп</p>\r\n<p>&bull; Поддержание гигиены и лёгкости в ногах</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-04-20 04:01:57'),
(4, 'Pediküür “Sügavniisutus”/Педикюр «Глубокое увлажнение»', '#b8b7d8', 65.00, 0, NULL, 150, 'Parafiiniteraapia koos klassikalise pediküüriga/Парафиновая терапия с классическим педикюром', '<p>Parafiiniteraapia koos klassikalise pedik&uuml;&uuml;riga</p>\r\n<p>Kompleksne protseduur, mis &uuml;hendab klassikalise pedik&uuml;&uuml;ri ja sooja parafiiniteraapia: varbak&uuml;&uuml;ned ja jalataldade nahk t&ouml;&ouml;deldakse hoolikalt, seej&auml;rel kantakse peale parafiin, mis niisutab s&uuml;gavuti, pehmendab nahka ja parandab vereringet.<br><br></p>\r\n<p>Парафиновая терапия с классическим педикюром</p>\r\n<p>Комплексная процедура, сочетающая классический педикюр с тёплой парафиновой терапией: ногти и кожа стоп тщательно обрабатываются, затем наносится парафин, который глубоко увлажняет, смягчает кожу и улучшает кровообращение.</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-01-01 19:56:04'),
(5, 'Pediküür «Esteetika»/Педикюр «Эстетика»', '#a057af', 50.00, 0, NULL, 120, 'Pediküür «Esteetika» on klassikalise jalahoolduse ja geellaki pealekandmise kombinatsioon./Педикюр «Эстетика» — это сочетание классического ухода за стопами и ногтями с нанесением гель-лака.', '<p>Pedik&uuml;&uuml;r &laquo;Esteetika&raquo; on klassikalise jalahoolduse ja geellaki pealekandmise kombinatsioon./Педикюр &laquo;Эстетика&raquo; &mdash; это сочетание классического ухода за стопами и ногтями с нанесением гель-лака.</p>', 1, NULL, NULL, 0, 1, '2025-03-29 23:51:10', '2025-09-11 17:07:27'),
(6, 'Sissekasvanud küünte korrigeerimine ja töötlemine/Коррекция и обработка вросших ногтей', '#25fb39', 25.00, 1, 20, 60, 'Aitab eemaldada sissekasvanud küüne, leevendada valu ja vältida põletikku./Помогает устранить врастание ногтя, снять болезненные ощущения и избежать воспаления.\r\nобработка 1 ногтя 25€/ 2 ногтя от 35€', '<p>Protseduur viiakse l&auml;bi steriilsetes tingimustes ja on suunatud sissekasvanud k&uuml;&uuml;ne ohutule eemaldamisele. Kasutatakse kaasaegseid korrektsioonimeetodeid.</p>\r\n<p><br>Процедура проводится в стерильных условиях и направлена на безопасное устранение вросшего ногтя. Используются современные методики коррекции.</p>\r\n<p>обработка 1 ногтя 25&euro;/ 2 ногтя от 35&euro;</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-01-01 20:04:02'),
(7, 'Pragude töötlemine/Обработка трещин', '#10fc45', 25.00, 1, 30, 60, 'Vabastab kuivusest, sarvestunud nahast ja valulikest pragudest./Избавляет от сухости, огрубевшей кожи и болезненных трещин.', '<p>Pragude t&ouml;&ouml;tlemine &ndash; protseduur, mis on suunatud valulike kandade ja jalataldade pragude puhastamisele, silumisele ja paranemise soodustamisele, taastades naha pehmuse ja kaitsefunktsiooni.</p>\r\n<p>Обработка трещин &mdash; процедура, направленная на очищение, сглаживание и заживление болезненных трещин на пятках и стопах, с восстановлением мягкости и защитных функций кожи.</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-04-19 10:44:11'),
(8, 'Ainult jalataldade hooldus / Обработка стоп', '#ed55b9', 40.00, 1, NULL, 60, 'Jalataldade töötlemine on protseduur, mis eemaldab sarvestunud naha ja taastab jalgade pehmuse./Обработка стоп — это процедура, направленная на удаление огрубевшей кожи и восстановление мягкости стоп.', '<p>Jalataldade t&ouml;&ouml;tlemine &ndash; hooldusprotseduur, mille k&auml;igus eemaldatakse sarvestunud nahk, pehmendatakse ja silutakse tallad, et taastada naha pehmus ja ennetada paksendite teket.</p>\r\n<p><br>Обработка стоп &mdash; это уходовая процедура, при которой удаляется ороговевшая кожа, смягчаются и выравниваются подошвы для восстановления мягкости и профилактики огрубения.</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-04-19 10:44:58'),
(9, 'Küünte lõikamine/ стрижка ногтей', '#3880fd', 25.00, 1, NULL, 60, 'Küünte lühendamine ja pikkuse ühtlustamine vastavalt anatoomilisele kujule.\r\n\r\nIlma naha töötlemise ja katteta./\r\n\r\nПодрезание и выравнивание длины ногтей с соблюдением анатомической формы.\r\n\r\nБез обработки кожи и без покрытия.', '<p>K&uuml;&uuml;nte l&uuml;hendamine ja pikkuse &uuml;htlustamine vastavalt anatoomilisele kujule.</p>\r\n<p>Ilma naha t&ouml;&ouml;tlemise ja katteta./</p>\r\n<p>Подрезание и выравнивание длины ногтей с соблюдением анатомической формы.</p>\r\n<p>Без обработки кожи и без покрытия.</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-01-01 19:47:57'),
(10, '“Parafiiniteraapia”/Парафинотерапия', '#fab5c5', 25.00, 0, NULL, 30, 'Niisutab sügavuti, toidab ja pehmendab nahka./Глубоко увлажняет, питает и смягчает кожу.', '<p>Jalaparafiiniteraapia</p>\r\n<p>Niisutab s&uuml;gavuti, pehmendab nahka ja parandab vereringet. Soe parafiin katab jalad, avab poorid ja aitab toitainetel paremini imenduda.</p>\r\n<p>N&auml;idustused:</p>\r\n<p>&bull; Kuiv, l&otilde;henenud nahk</p>\r\n<p>&bull; V&auml;simus- ja pingetunne jalgades</p>\r\n<p>&bull; Sobib h&auml;sti k&uuml;lmal aastaajal naha pehmuse ja soojuse taastamiseks</p>\r\n<p>Tulemus:</p>\r\n<p>Sile ja hoolitsetud nahk ning m&otilde;nus kergustunne jalgades.</p>\r\n<p><br>Парафиновая терапия для ног</p>\r\n<p>Глубоко увлажняет, смягчает кожу и улучшает кровообращение. Тёплый парафин обволакивает стопы, открывая поры и способствуя проникновению питательных веществ.</p>\r\n<p>Показания:</p>\r\n<p>&bull; Сухая, потрескавшаяся кожа</p>\r\n<p>&bull; Чувство усталости и напряжения</p>\r\n<p>&bull; Подходит в холодное время года для восстановления мягкости и тепла</p>\r\n<p>Результат:</p>\r\n<p>Гладкая, ухоженная кожа и приятное ощущение лёгкости в ногах.</p>', 1, NULL, NULL, 0, 0, '2025-03-29 23:51:10', '2026-01-01 19:42:32'),
(11, 'Parafiiniteraapia „Kompleks“/Парафинотерапия «Комплекс»', '#c26e1e', 70.00, 1, NULL, 30, 'Niisutab sügavuti, toidab ja pehmendab nahka./Глубоко увлажняет, питает и смягчает кожу.', '<p>Niisutab s&uuml;gavuti, toidab ja pehmendab nahka.</p>\r\n<p>5 protseduuri &ndash; 70 &euro;</p>\r\n<p>10 protseduuri &ndash; 130 &euro;<br><br></p>\r\n<p>Глубоко увлажняет, питает и смягчает кожу.</p>\r\n<p>5 процедур &ndash; 70&euro;<br>10 процедур &ndash; 130&euro;</p>', 1, NULL, NULL, 0, 1, '2025-03-29 23:51:10', '2026-01-01 19:41:59'),
(12, 'SOS-teenus/СОС-Услуга', '#eef3b0', 50.00, 0, NULL, 45, 'Kiirprotseduur, saadaval ainult kell 8:15 hommikul./Экстренная процедура, доступна только в 8:15 утра.', '<p>Protseduur on suunatud valu p&otilde;hjuste k&otilde;rvaldamisele, mis on tingitud sissekasvanud k&uuml;&uuml;ntest, konnasilmadest, paksenditest v&otilde;i l&otilde;hedest, pakkudes seej&auml;rel leevendust ja taastades jalgade mugavuse.</p>\r\n<p><br>Процедура направлена на устранение причины боли, вызванной вросшими ногтями, мозолями, натоптышами или трещинами, с последующим облегчением состояния и восстановлением комфорта.</p>', 1, '08:15:00', '09:00:00', 1, 0, '2025-03-29 23:51:10', '2026-01-01 19:41:40'),
(13, 'Консультация', '#8daeb2', 15.00, 0, NULL, 15, NULL, NULL, 1, NULL, NULL, 0, 1, '2025-03-29 23:51:10', '2025-04-12 12:15:07'),
(14, 'test', '#38871c', 50.00, 1, NULL, 60, 'gegeerh', '<p>rhreher erh re</p>', 1, NULL, NULL, 0, 1, '2025-04-01 09:14:14', '2025-04-01 09:14:28'),
(15, 'Tets', '#7398e2', 50.00, 1, NULL, 60, NULL, NULL, 1, NULL, NULL, 0, 1, '2025-04-03 07:03:27', '2025-04-03 07:03:42'),
(16, '“Konnasilmade ja paksendite eemaldamine”/Удаление мозолей и натоптышей', '#e7c500', 25.00, 1, NULL, 60, 'Konnasilmade ja paksendite eemaldamine”/Удаление мозолей и натоптышей', '<p>Konnasilmade ja paksendite eemaldamine h&otilde;lmab jalgade naha &otilde;rna t&ouml;&ouml;tlemist professionaalsete t&ouml;&ouml;riistade ja vahenditega, mis on suunatud sarvestunud piirkondade k&otilde;rvaldamisele ja naha pehmuse taastamisele. See aitab v&auml;hendada k&otilde;ndimisel tekkivat ebamugavust ja ennetada probleemsete piirkondade taasteket.</p>\r\n<p><br>Процедура удаления мозолей и натоптышей включает в себя бережную обработку кожи стоп с использованием профессиональных инструментов и средств, направленных на устранение ороговевших участков и восстановление мягкости кожи. Это способствует снижению дискомфорта при ходьбе и предотвращает повторное образование проблемных зон.</p>', 1, NULL, NULL, 0, 0, '2025-04-03 07:10:22', '2025-06-18 08:22:03'),
(17, 'test', '#73e275', 50.00, 0, NULL, 60, 'hhhh', NULL, 1, NULL, NULL, 0, 1, '2025-04-03 07:15:09', '2025-04-03 07:15:15'),
(18, 'Удаление мозолей', '#496397', 20.00, 1, NULL, 60, 'Удаление мозолей', NULL, 1, NULL, NULL, 0, 1, '2025-04-03 07:17:34', '2025-04-03 07:17:41'),
(19, 'Удаление мозолей и натоптышей', '#e273df', 20.00, 1, NULL, 60, 'Удаление мозолей и натоптышей', NULL, 1, NULL, NULL, 0, 1, '2025-04-03 08:33:14', '2025-04-03 08:33:22'),
